	public static void Main(Args _args)
    {
        FTDBookInventoryUpdationController controller = FTDBookInventoryUpdationController::Construct();

        controller.initFromBookFormIfNeeded(_args);

        if(controller.prompt())
        {
            controller.runOperation();
        }
    }

protected void new(IdentifierName _className = '', 
    IdentifierName _methodName = '', 
    SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    super(_className, _methodName, _executionMode);
}

public void initFromBookFormIfNeeded(Args _args)
{
    FormRun callerFormRun = _args.caller();

    if (callerFormRun
        && callerFormRun.name() == formStr(FTDBook))
    {
        //recupera el registro activo del formulario
        FTDBookTable bookActiveRecord = callerFormRun
            .dataSource(formDataSourceStr(FTDBook, FTDBookTable))
            .cursor();

        FTDBookInventoryUpdationDataContract contract = this.getDatacontract();

        contract.parmBookId(bookActiveRecord.Id);
    }
}

public boolean validateParameters()
{
    boolean ret = super();

    if (ret)
    {
        FTDBookInventoryUpdationDataContract dataContract = this.getDatacontract();
        ret = this.validateBook(dataContract.parmBookId()) 
            && this.validateNewQty(dataContract.parmNewQty());
    }

    return ret;
}

public boolean validateBook(FTDId _bookId)
{
    if (!FTDBookTable::exist(_bookId))
    {
        return checkFailed(strFmt("@ITFormacion:Book1DoesNotExists", _bookId));
    }

    return true;
}

public boolean validateNewQty(Qty _newQty)
{
    if (_newQty < 0)
    {
        return checkfailed("@ITFormacion:TransactionWouldMakeTheTotalNegative");
    }

    return true;
}

public static FTDBookInventoryUpdationController Construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    FTDBookInventoryUpdationController controller =  new FTDBookInventoryUpdationController(classStr(FTDBookInventoryUpdationService),
        methodStr(FTDBookInventoryUpdationService, runProcess),
        _executionMode);

    controller.parmDialogCaption("@ITFormacion:UpdateBookInventory");

    return controller;
}
